<script lang="ts">
  import type { PageData } from './$types';
  export let data: PageData;
  let search = '';
  let sortBy: 'units' | 'cost' = 'units';
  $: report = data.report;
  $: shipments = (report?.shipments ?? [])
    .filter((s) => `${s.warehouseId} ${s.storeId}`.toLowerCase().includes(search.toLowerCase()))
    .slice()
    .sort((a, b) => sortBy === 'units' ? b.units - a.units : b.transportCost - a.transportCost);
  const fmt = (n: number) => new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(n);
  const percent = (n: number, d: number) => d ? `${(100 * n / d).toFixed(1)}%` : '—';
</script>

<svelte:head>
  <title>OptiFlow | Allocation Intelligence</title>
  <meta name="description" content="Supply-chain inventory optimization and allocation analysis" />
</svelte:head>

<div class="shell">
  <aside class="sidebar">
    <div class="brand"><span class="logo">◈</span> OptiFlow <small>STUDIO</small></div>
    <div class="nav active">▦ &nbsp; Allocation overview</div>
    <div class="nav muted">◇ &nbsp; Scenario lab <span>SOON</span></div>
    <div class="nav muted">▤ &nbsp; Data pipeline <span>SOON</span></div>
    <div class="sidefoot">LOCAL ANALYTICS<br /><strong>Snapshot mode</strong><p>Generated by the Scala OR-Tools engine. No live backend connection.</p></div>
  </aside>
  <main>
    <header><div><div class="eyebrow">SUPPLY CHAIN / ALLOCATION</div><h1>Network overview</h1><p class="sub">Explore the optimal inventory distribution across your network.</p></div><div class="badge">● &nbsp; {report ? 'Snapshot loaded' : 'Awaiting data'}</div></header>
    {#if data.error}
      <section class="empty"><h2>No allocation report yet</h2><p>{data.error}</p><code>sbt "runMain optiflow.AllocationReportCli datasets/demo output/allocation.json"</code></section>
    {:else if report}
      <div class="metrics">
        <article class="metric"><div class="label">Demand fulfillment</div><strong>{percent(report.summary.fulfilledUnits, report.summary.totalDemand)}</strong><div class="hint">{fmt(report.summary.fulfilledUnits)} of {fmt(report.summary.totalDemand)} units</div></article>
        <article class="metric"><div class="label">Optimized total cost</div><strong>{fmt(report.summary.optimizedCost)}</strong><div class="hint">Dataset monetary units</div></article>
        <article class="metric"><div class="label">Savings vs. greedy</div><strong>{fmt(report.summary.savingsVsGreedy)}</strong><div class="hint">Baseline: {fmt(report.summary.greedyCost)}</div></article>
        <article class="metric"><div class="label">Unmet demand</div><strong>{fmt(report.summary.unfulfilledUnits)}</strong><div class="hint">Penalty: {fmt(report.shortagePenalty)} per unit</div></article>
      </div>
      <div class="two">
        <section class="panel"><div class="panelhead"><div><div class="eyebrow">DEMAND COVERAGE</div><h2>Store fulfillment</h2></div><span>{report.stores.length} stores</span></div>
          {#each report.stores as store (store.id)}
            <div class="barrow"><div class="barlabel"><strong>{store.id}</strong><span>{fmt(store.demand - store.unmet)} / {fmt(store.demand)}</span></div><div class="track"><div class="fill" style:width={percent(store.demand - store.unmet, store.demand).replace('—','0%')}></div></div></div>
          {/each}
        </section>
        <section class="panel"><div class="panelhead"><div><div class="eyebrow">CAPACITY</div><h2>Warehouse utilization</h2></div><span>{report.warehouses.length} warehouses</span></div>
          {#each report.warehouses as warehouse (warehouse.id)}
            {@const allocated = report.shipments.filter((s) => s.warehouseId === warehouse.id).reduce((sum, s) => sum + s.units, 0)}
            {@const available = Math.min(warehouse.inventory, warehouse.outboundCapacity)}
            <div class="barrow"><div class="barlabel"><strong>{warehouse.id}</strong><span>{fmt(allocated)} / {fmt(available)}</span></div><div class="track"><div class="fill teal" style:width={percent(allocated, available).replace('—','0%')}></div></div></div>
          {/each}
        </section>
      </div>
      <section class="panel tablepanel"><div class="panelhead"><div><div class="eyebrow">OPTIMAL ROUTING</div><h2>Shipment allocations</h2></div><div class="tools"><input aria-label="Search routes" placeholder="Search warehouse or store" bind:value={search} /><select aria-label="Sort shipments" bind:value={sortBy}><option value="units">Most units</option><option value="cost">Highest cost</option></select></div></div>
        <div class="tablewrap"><table><thead><tr><th>ORIGIN</th><th>DESTINATION</th><th>UNITS</th><th>UNIT COST</th><th>TRANSPORT COST</th></tr></thead><tbody>{#each shipments as shipment (shipment.warehouseId + shipment.storeId)}<tr><td>{shipment.warehouseId}</td><td>{shipment.storeId}</td><td><strong>{fmt(shipment.units)}</strong></td><td>{fmt(shipment.unitCost)}</td><td>{fmt(shipment.transportCost)}</td></tr>{:else}<tr><td colspan="5">No matching shipments</td></tr>{/each}</tbody></table></div>
      </section>
      <footer>Solver: {report.status} · Transport: {fmt(report.summary.transportationCost)} · Shortage penalty cost: {fmt(report.summary.shortageCost)} · Schema v{report.schemaVersion}</footer>
    {/if}
  </main>
</div>

