ize:11px;color:#7890a8;margin:15px 0 30px}.empty{padding:32px}.empty p{color:#b5c5d8}.empty code{display:block;overflow-wrap:anywhere;color:#65e2c8;background:#0d1828;padding:15px;border-radius:8px}
  @media(max-width:1100px){.metrics{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}main{padding:35px 25px}}@media(max-width:720px){.shell{display:block}.sidebar{width:auto;padding:18px}.brand{padding:0}.nav,.sidefoot{display:none}main{padding:26px 15px}header{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:1fr 1fr;gap:10px}.metric{padding:17px}.metric strong{font-size:24px}.panel{padding:17px}.panelhead{flex-wrap:wrap}.tools{width:100%;flex-wrap:wrap}}
